parameters.text:
=You are a meticulous loan document verification specialist.

Applicant declared:
Name: {{ $json.applicantName }}
Date of Birth: {{ $json.dateOfBirth }}
Employer: {{ $json.employerName }}
Self-Reported Monthly Income: {{ $json.monthlyIncome }}

Documents provided (raw extracted text):
ID Document: {{ $json.idDocumentText }}
Income Proof: {{ $json.incomeProofText }}
Bank Statement: {{ $json.bankStatementText }}

Your task:
1. Extract structured data from each document.
2. Cross-check the extracted name, employer, and income against what the applicant declared.
3. Flag any document that is missing, illegible, incomplete, or looks inconsistent or fabricated.

Return a JSON object with EXACTLY these fields:
{
  "documentsComplete": true or false,
  "extractedName": "Name found on the ID document",
  "extractedDOB": "Date of birth found on the ID document",
  "extractedIdNumber": "ID number found on the ID document",
  "extractedEmployer": "Employer found on the income proof",
  "extractedMonthlyIncome": <number, monthly income found on the income proof>,
  "bankAverageBalance": <number, average balance found on the bank statement>,
  "bankAverageMonthlyDeposit": <number, average monthly deposit found on the bank statement>,
  "overdraftCount": <integer, number of overdrafts mentioned>,
  "consistencyIssues": ["issue1", "issue2"],
  "verificationNotes": "Brief summary of the verification outcome",
  "verificationScore": <number 1-10, 10 = fully complete, consistent, verifiable documents>
}

If no consistency issues are found, return an empty array. Return ONLY the JSON. No markdown, no explanation.

parameters.jsCode:
const item = $input.item.json;
let parsed = {};
try {
  const rawText = item.output || item.text || item.response || '{}';
  const clean = rawText.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch(e) {
  parsed = {
    documentsComplete: true,
    extractedName: item.applicantName,
    extractedDOB: item.dateOfBirth,
    extractedIdNumber: 'Unavailable',
    extractedEmployer: item.employerName,
    extractedMonthlyIncome: item.monthlyIncome,
    bankAverageBalance: 0,
    bankAverageMonthlyDeposit: item.monthlyIncome,
    overdraftCount: 0,
    consistencyIssues: [],
    verificationNotes: 'Auto-passed: could not parse AI verification output, trusting self-reported figures',
    verificationScore: 5
  };
}
return { json: { ...item, ...parsed } };

const item = $input.item.json;
const verifiedIncome = (item.extractedMonthlyIncome && item.extractedMonthlyIncome > 0) ? item.extractedMonthlyIncome : item.monthlyIncome;
const existingDebt = item.existingMonthlyDebt || 0;

// Estimate an illustrative interest rate tier from self-reported credit score
const creditScore = item.selfReportedCreditScore || 650;
let annualRatePercent;
if (creditScore >= 740) annualRatePercent = 7.5;
else if (creditScore >= 670) annualRatePercent = 10.5;
else if (creditScore >= 580) annualRatePercent = 15.0;
else annualRatePercent = 22.0;

const monthlyRate = annualRatePercent / 100 / 12;
const n = item.requestedTermMonths || 36;
const principal = item.loanAmount || 0;
const estimatedMonthlyInstallment = monthlyRate > 0
  ? Math.round((principal * monthlyRate) / (1 - Math.pow(1 + monthlyRate, -n)) * 100) / 100
  : Math.round((principal / n) * 100) / 100;

const debtToIncomeRatio = verifiedIncome > 0 ? Math.round(((existingDebt + estimatedMonthlyInstallment) / verifiedIncome) * 100) : 100;
const loanToAnnualIncomeRatio = verifiedIncome > 0 ? Math.round((principal / (verifiedIncome * 12)) * 100) : 100;
const disposableIncomeAfterLoan = Math.round((verifiedIncome - existingDebt - estimatedMonthlyInstallment) * 100) / 100;

// Component scores, 0-100, higher is better (lower risk)
const creditComponent = Math.max(0, Math.min(100, ((creditScore - 300) / (850 - 300)) * 100));
const dtiComponent = Math.max(0, 100 - debtToIncomeRatio);
const tenureComponent = Math.min(100, (item.yearsEmployed || 0) * 20);
const bankHealthComponent = Math.max(0, 100 - (item.overdraftCount || 0) * 25);
const consistencyComponent = Math.max(0, 100 - ((item.consistencyIssues ? item.consistencyIssues.length : 0) * 20));

const compositeScore = Math.round(
  creditComponent * 0.35 +
  dtiComponent * 0.30 +
  tenureComponent * 0.15 +
  bankHealthComponent * 0.10 +
  consistencyComponent * 0.10
);

const riskScore = 100 - compositeScore;
let riskTier = 'Low Risk';
if (riskScore >= 70) riskTier = 'Very High Risk';
else if (riskScore >= 50) riskTier = 'High Risk';
else if (riskScore >= 30) riskTier = 'Medium Risk';

return {
  json: {
    ...item,
    verifiedMonthlyIncome: verifiedIncome,
    annualRatePercent,
    estimatedMonthlyInstallment,
    debtToIncomeRatio,
    loanToAnnualIncomeRatio,
    disposableIncomeAfterLoan,
    riskScore,
    riskTier
  }
};

parameters.text:
=You are an underwriting assistant producing a recommendation for a human loan officer, not a final automated decision.

Applicant: {{ $json.applicantName }}
Loan Amount Requested: {{ $json.loanAmount }}
Loan Purpose: {{ $json.loanPurpose }}
Requested Term: {{ $json.requestedTermMonths }} months
Employment: {{ $json.employmentStatus }}, {{ $json.yearsEmployed }} years at current employer
Self-Reported Credit Score: {{ $json.selfReportedCreditScore }}
Verified Monthly Income: {{ $json.verifiedMonthlyIncome }}
Estimated Monthly Installment: {{ $json.estimatedMonthlyInstallment }} at {{ $json.annualRatePercent }}% illustrative annual rate
Debt-to-Income Ratio: {{ $json.debtToIncomeRatio }}%
Loan-to-Annual-Income Ratio: {{ $json.loanToAnnualIncomeRatio }}%
Disposable Income After Loan: {{ $json.disposableIncomeAfterLoan }}
Risk Score: {{ $json.riskScore }}/100 ({{ $json.riskTier }})
Document Consistency Issues: {{ JSON.stringify($json.consistencyIssues) }}
Verification Notes: {{ $json.verificationNotes }}

Guidance: Very High Risk or a debt-to-income ratio above 50% should generally lean toward Manual Review or Decline. Medium or High Risk with minor issues can lean toward Conditional Approval with specific conditions. Low Risk with no consistency issues can lean toward Approve. Always ground your reasoning in the actual numbers above.

Return a JSON object with EXACTLY these fields:
{
  "recommendation": "Approve|Conditional Approval|Manual Review|Decline",
  "reasoning": "Two to four sentences referencing the specific numbers above",
  "conditions": ["condition1", "condition2"],
  "suggestedLoanAmount": <number, may equal the requested amount or be a lower counteroffer>,
  "recommendationConfidence": <number 0-100>
}

If no conditions apply, return an empty array. Return ONLY the JSON. No markdown, no explanation.

parameters.jsCode:
const item = $input.item.json;
let parsed = {};
try {
  const rawText = item.output || item.text || item.response || '{}';
  const clean = rawText.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch(e) {
  parsed = {
    recommendation: 'Manual Review',
    reasoning: 'Auto-flagged: could not parse AI eligibility output, routing to a human underwriter as a precaution.',
    conditions: [],
    suggestedLoanAmount: item.loanAmount,
    recommendationConfidence: 50
  };
}
return { json: { ...item, ...parsed } };

const item = $input.item.json;
const decidedAt = new Date().toISOString();

return {
  json: {
    ...item,
    decidedAt,
    applicationSummaryRow: [
      item.applicationId || 'N/A',
      item.applicantName || '',
      item.applicantEmail || '',
      item.loanAmount || 0,
      item.loanPurpose || '',
      item.requestedTermMonths || 0,
      item.verifiedMonthlyIncome || 0,
      (item.debtToIncomeRatio || 0) + '%',
      item.riskScore || 0,
      item.riskTier || '',
      item.recommendation || '',
      item.suggestedLoanAmount || 0,
      decidedAt
    ]
  }
};

